import Link from 'next/link'
import { ArrowLeft } from 'lucide-react'
import { ecoles } from '@/lib/ecoles'

export default function EcolesPage() {
  return (
    <main className="bg-gradient-to-b from-background to-blue-50/30">
      <div className="max-w-6xl mx-auto px-3 sm:px-4 lg:px-6 py-4 sm:py-6 pb-8">
        <Link
          href="/"
          className="inline-flex items-center gap-1.5 text-xs sm:text-sm text-primary hover:text-primary/80 transition mb-4"
        >
          <ArrowLeft className="w-3.5 h-3.5 sm:w-4 sm:h-4 shrink-0" />
          Retour à l&apos;accueil
        </Link>

        <div className="space-y-2 mb-6">
          <h1 className="text-2xl sm:text-3xl md:text-4xl font-bold text-primary leading-tight">
            Nos Écoles de Formation
          </h1>
          <p className="text-sm sm:text-base text-foreground/75 leading-relaxed max-w-3xl">
            Chaque école dispose de sa propre page avec le programme, les informations pratiques et les modalités
            d&apos;inscription.
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-4">
          {ecoles.map((school) => (
            <Link
              key={school.slug}
              href={school.href}
              className="group rounded-xl border bg-white p-4 shadow-sm hover:shadow-md hover:border-primary/30 transition-all"
            >
              <div className="flex items-start justify-between gap-2 mb-2">
                <h2 className="text-sm sm:text-base font-bold text-foreground group-hover:text-primary transition-colors leading-snug">
                  {school.title}
                </h2>
                {school.status ? (
                  <span
                    className={`shrink-0 text-[10px] font-medium px-2 py-0.5 rounded-full ${school.statusColor ?? 'bg-muted text-muted-foreground'}`}
                  >
                    {school.status}
                  </span>
                ) : null}
              </div>
              <p className="text-xs sm:text-sm text-foreground/65 leading-relaxed mb-3">{school.description}</p>
              <span className="text-xs font-semibold text-primary">Voir la page →</span>
            </Link>
          ))}
        </div>

        <div className="mt-10 text-center rounded-xl border bg-white p-5 sm:p-6">
          <h2 className="text-lg font-bold text-foreground mb-2">Prêt à vous inscrire ?</h2>
          <p className="text-sm text-foreground/65 mb-4 max-w-xl mx-auto">
            Consultez la page de l&apos;école qui vous intéresse, puis remplissez le formulaire d&apos;inscription.
          </p>
          <div className="flex flex-col sm:flex-row gap-2 justify-center">
            <Link
              href="/inscription"
              className="px-5 py-2.5 bg-primary text-primary-foreground rounded-lg text-sm font-semibold hover:bg-primary/90 transition"
            >
              S&apos;inscrire
            </Link>
            <Link
              href="/contact"
              className="px-5 py-2.5 border border-primary text-primary rounded-lg text-sm font-semibold hover:bg-primary/5 transition"
            >
              Nous contacter
            </Link>
          </div>
        </div>
      </div>
    </main>
  )
}
